var data = $input.first().json;
var input = $('Webhook').first().json.body;

var session = null;
if (Array.isArray(data) && data.length > 0) {
  session = data[0];
} else if (data && typeof data === 'object' && data.id) {
  session = data;
}

if (!session) {
  return [{
    json: {
      error: 'no_route_selected',
      message: 'No route is currently selected. Please tell me which route you want to work on first.',
      spoken: 'I need to know which route you want to work on first. Which route would you like to start?'
    }
  }];
}

var direction = input.direction || 'beginning';
var pickDirection = (direction === 'end' || direction === 'bottom' || direction === 'last') ? 'reverse' : 'forward';

return [{
  json: {
    session_id: session.id,
    machine_id: session.current_machine_id,
    current_route_id: session.current_route_id,
    pick_direction: pickDirection,
    has_session: true
  }
}];

var extractData = $('Extract Session').first().json;
if (extractData.error) {
  return [{ json: extractData }];
}

var sessionData = extractData;
var itemsData = $input.all();

var items = [];
for (var i = 0; i < itemsData.length; i++) {
  var item = itemsData[i].json;
  if (item && item.id) {
    items.push(item);
  }
}

if (items.length === 0) {
  return [{
    json: {
      error: 'No items found in machine',
      session_id: sessionData.session_id
    }
  }];
}

var selectedItem;
var itemIndex;

if (sessionData.pick_direction === 'reverse') {
  selectedItem = items[items.length - 1];
  itemIndex = items.length;
} else {
  selectedItem = items[0];
  itemIndex = 1;
}

return [{
  json: {
    session_id: sessionData.session_id,
    current_route_id: sessionData.current_route_id,
    pick_direction: sessionData.pick_direction,
    current_item_index: itemIndex,
    product_name: selectedItem.product_name,
    quantity: selectedItem.quantity,
    slot: selectedItem.slot,
    inventory_current: selectedItem.inventory_current || 0,
    inventory_parlevel: selectedItem.inventory_parlevel || 0,
    total_items: items.length
  }
}];

var selectData = $('Select Item').first().json;

if (selectData.error) {
  return [{ json: selectData }];
}

var data = selectData;

function parseProduct(productName) {
  if (!productName) return { name: '', size: '', type: '' };
  var text = productName.trim();
  var sizePattern = /(\d+(?:\.\d+)?)\s*(oz|ounce|ml|g|gram|ct|count|pk|pack)/gi;
  var sizeMatch = sizePattern.exec(text);
  var size = sizeMatch ? sizeMatch[0] : '';
  var typePattern = /\b(can|bottle|bag|box|bar|pouch|packet|pack)\b/gi;
  var typeMatch = typePattern.exec(text);
  var type = typeMatch ? typeMatch[0] : '';
  var name = text;
  if (size) { name = name.replace(sizePattern, '').trim(); }
  if (type) {
    var typeWord = typeMatch[0];
    name = name.replace(new RegExp('\\s*' + typeWord + '\\s*$', 'gi'), '');
    name = name.replace(new RegExp('\\s*' + typeWord + '\\s*-', 'gi'), ' -');
  }
  name = name.replace(/\s+/g, ' ').trim();
  name = name.replace(/\s*-\s*$/, '').trim();
  name = name.replace(/\(\s*\)/, '').trim();
  return { name: name, size: size, type: type };
}

function fixPronunciation(text) {
  if (!text) return text;
  text = text.replace(/\bCan\b/g, 'Kan');
  text = text.replace(/\bCAN\b/g, 'KAN');
  text = text.replace(/\boz\b/gi, 'ounce');
  text = text.replace(/\bct\b/gi, 'count');
  text = text.replace(/\bpk\b/gi, 'pack');
  return text;
}

function formatSlotForTTS(slot) {
  if (!slot) return null;
  slot = String(slot);
  if (slot.indexOf('-') !== -1) {
    var parts = slot.split('-');
    var first = parseInt(parts[0], 10);
    var second = parseInt(parts[1], 10);
    if (!isNaN(first) && !isNaN(second)) {
      return 'slots ' + first + ' and ' + second;
    }
    return slot;
  }
  var num = parseInt(slot, 10);
  if (!isNaN(num)) { return 'slot ' + num; }
  return slot;
}

var parsed = parseProduct(data.product_name);
var slotSpoken = formatSlotForTTS(data.slot);
var parts = [];
parts.push(data.quantity);
if (parsed.name) { parts.push(fixPronunciation(parsed.name)); }
if (parsed.size) { parts.push(fixPronunciation(parsed.size)); }
if (parsed.type) {
  var typeLower = parsed.type.toLowerCase();
  var nameLower = parsed.name.toLowerCase();
  if (nameLower.indexOf(typeLower) === -1) {
    parts.push(fixPronunciation(parsed.type));
  }
}
var spoken = parts.join(' ');
var directionWord = data.pick_direction === 'reverse' ? 'bottom' : 'top';
spoken = 'Starting from ' + directionWord + '. ' + spoken;

return [{
  json: {
    action: 'item_ready',
    product_name: data.product_name,
    quantity: data.quantity,
    slot: data.slot,
    slot_spoken: slotSpoken,
    inventory_current: data.inventory_current || 0,
    inventory_parlevel: data.inventory_parlevel || 0,
    items_remaining: data.total_items - 1,
    direction: data.pick_direction,
    product_parsed: { name: parsed.name, size: parsed.size, type: parsed.type },
    spoken: spoken
  }
}];
